type MailPagePayload struct{Limit uint16 `json:"limit"`;Cursor string `json:"cursor,omitempty"`}
type MailPageResult struct{Items []mail.ResourceEnvelope `json:"items"`;NextCursor string `json:"next_cursor,omitempty"`}
type MailDomainPayload struct{Domain mail.Domain `json:"domain"`}
type MailMailboxPayload struct{Mailbox mail.Mailbox `json:"mailbox"`}
type MailAliasPayload struct{Alias mail.Alias `json:"alias"`}
type MailPolicyPayload struct{Policy mail.Policy `json:"policy"`}
type MailDKIMPreparePayload struct{OverlapSeconds uint32 `json:"overlap_seconds,omitempty"`;CurrentSecretVersion uint64 `json:"current_secret_version,omitempty"`;CurrentSecretBindingDigest string `json:"current_secret_binding_digest,omitempty"`;CurrentSecretResourceGeneration uint64 `json:"current_secret_resource_generation,omitempty"`}
type MailDKIMActivatePayload struct{ConfirmPrevious bool `json:"confirm_previous,omitempty"`}
type MailQueueFlushPayload struct{Limit uint16 `json:"limit,omitempty"`;Cursor string `json:"cursor,omitempty"`}
