type WebmailSessionIssuePayload struct{TTLSeconds uint32 `json:"ttl_seconds"`}
type WebmailFoldersPayload struct{Session mail.MailSession `json:"session"`;MailboxID mail.MailboxID `json:"mailbox_id,omitempty"`}
type WebmailSearchPayload struct{Session mail.MailSession `json:"session"`;MailboxID mail.MailboxID `json:"mailbox_id,omitempty"`;Query mail.MessageQuery `json:"query"`;FolderID mail.FolderID `json:"folder_id,omitempty"`;Terms string `json:"terms,omitempty"`;Cursor string `json:"cursor,omitempty"`;Limit uint16 `json:"limit,omitempty"`;Sort string `json:"sort,omitempty"`}
